func (p *PortDefinition) UnmarshalJSON(data []byte) error {
	var wire struct {
		Name        string          `json:"name"`
		Required    bool            `json:"required,omitempty"`
		Description string          `json:"description,omitempty"`
		External    bool            `json:"external,omitempty"`
		Config      json.RawMessage `json:"config"`
	}
	if err := decodeStrict(data, &wire); err != nil {
		return portConfigError(wire.Name, rawPortableKind(wire.Config), "definition", err)
	}
	if strings.TrimSpace(wire.Name) == "" {
		return portConfigError(wire.Name, rawPortableKind(wire.Config), "name", errors.New("field \"name\" is required"))
	}
	config, err := decodePortable(wire.Config)
	if err != nil {
		return portConfigError(wire.Name, rawPortableKind(wire.Config), "config", err)
	}
	*p = PortDefinition{
		Name:        wire.Name,
		Required:    wire.Required,
		Description: wire.Description,
		External:    wire.External,
		Config:      config,
	}
	return nil
}

func applyJetStreamConsumerConfig(cfg *ConsumerConfig, stream StreamFacts) error {
	if stream.DeliverPolicy() != "" {
		cfg.DeliverPolicy = stream.DeliverPolicy()
	}
	if stream.AckPolicy() != "" {
		cfg.AckPolicy = stream.AckPolicy()
	}
	if stream.MaxDeliver() > 0 {
		cfg.MaxDeliver = stream.MaxDeliver()
	}
	// MaxAckPending: a non-zero port value (including -1 = unlimited) overrides
	// the server default. 0 stays 0 (caller leaves the server default).
	if stream.MaxAckPending() != 0 {
		cfg.MaxAckPending = stream.MaxAckPending()
	}
	if stream.AckWait() != "" {
		duration, err := time.ParseDuration(stream.AckWait())
		if err != nil {
			return fmt.Errorf("parse ack_wait: %w", err)
		}
		cfg.AckWait = duration
	}
	if stream.HeartbeatInterval() != "" {
		duration, err := time.ParseDuration(stream.HeartbeatInterval())
		if err != nil {
			return fmt.Errorf("parse heartbeat_interval: %w", err)
		}
		cfg.HeartbeatInterval = duration
	}
	return nil
}

func GetFloat64(config map[string]any, key string, defaultValue float64) float64 {
	// Validate the key first
	if err := ValidateConfigKey(key); err != nil {
		return defaultValue
	}

	if value, exists := config[key]; exists {
		switch v := value.(type) {
		case float64:
			// Check for NaN and Inf values
			if math.IsNaN(v) || math.IsInf(v, 0) {
				return defaultValue
			}
			return v
		case float32:
			// Check for NaN and Inf values
			if math.IsNaN(float64(v)) || math.IsInf(float64(v), 0) {
				return defaultValue
			}
			return float64(v)
		case int:
			// Safe conversion from int to float64
			if v < MinInt || v > MaxInt {
				return defaultValue
			}
			return float64(v)
		case int64:
			// Check bounds for int64 to float64 conversion
			if v < int64(MinInt) || v > int64(MaxInt) {
				return defaultValue
			}
			return float64(v)
		}
	}
	return defaultValue
}

