func GetString(config map[string]any, key string, defaultValue string) string {
	// Validate the key first
	if err := ValidateConfigKey(key); err != nil {
		// Log warning but return default to maintain API compatibility
		return defaultValue
	}

	if value, exists := config[key]; exists {
		if str, ok := value.(string); ok {
			// Validate string length for security
			if len(str) > MaxStringLength {
				// Return default for oversized strings
				return defaultValue
			}
			// Sanitize string - remove null bytes and control characters except basic whitespace
			cleaned := strings.Map(func(r rune) rune {
				if r == '\x00' || (r < 32 && r != '\t' && r != '\n' && r != '\r') {
					return -1 // Remove invalid characters
				}
				return r
			}, str)
			return cleaned
		}
	}
	return defaultValue
}

func MergePortConfig(defaults, overrides PortConfig) (PortConfig, error) {
	inputs, err := mergePortDirection(defaults.Inputs, overrides.Inputs, DirectionInput)
	if err != nil {
		return PortConfig{}, err
	}
	outputs, err := mergePortDirection(defaults.Outputs, overrides.Outputs, DirectionOutput)
	if err != nil {
		return PortConfig{}, err
	}
	return PortConfig{Inputs: inputs, Outputs: outputs}, nil
}

