func ValidatePortNumber(port int) error {
	if port < MinPort || port > MaxPort {
		msg := fmt.Errorf("port %d outside valid range %d-%d", port, MinPort, MaxPort)
		return errs.WrapInvalid(msg, "ConfigValidator", "ValidatePortNumber",
