		return Declaration{}, err
	}
	return Declaration{
		InstanceName:       instanceName,
		FactoryIdentity:    config.Name,
		ComponentType:      config.Type,
		InputPorts:         inputs,
		OutputPorts:        outputs,
		InputFacts:         inputFacts,
		OutputFacts:        outputFacts,
