func validateDirectionRequirements(config Portable, direction Direction, binding portBinding) (string, error) {
	required := binding.requiredByDirection[direction]
	if len(required) == 0 {
		return "", nil
	}
	data, err := json.Marshal(config)
	if err != nil {
		return "config", fmt.Errorf("marshal direction requirements: %w", err)
	}
	var fields map[string]any
	if err := json.Unmarshal(data, &fields); err != nil {
		return "config", fmt.Errorf("decode direction requirements: %w", err)
	}
	for _, field := range required {
		value, exists := fields[field]
		if !exists || directionFieldEmpty(value) {
			return field, fmt.Errorf("field %q is required for direction %q", field, direction)
		}
	}
	return "", nil
}

func (r *Registry) createComponent(
	instanceName string,
	config types.ComponentConfig,
	deps Dependencies,
	prepare func(Discoverable) error,
) (Discoverable, error) {
	r.mu.RLock()
	sealed := r.sealed
	r.mu.RUnlock()
	if sealed {
		return nil, errs.WrapInvalid(
			errs.ErrInvalidConfig,
			"Registry", "CreateComponent", "component composition is sealed for this process",
		)
	}
	prepared, err := r.prepareComponent("CreateComponent", instanceName, config, deps)
	if err != nil {
		return nil, err
	}
	if prepare != nil {
		if err := prepare(prepared.component); err != nil {
			return nil, errs.Wrap(err, "Registry", "CreateComponent", "prepare managed component")
		}
	}
	if err := r.admitPrepared(prepared.declaration); err != nil {
		return nil, errs.Wrap(err, "Registry", "CreateComponent", "instance registration")
	}
	return prepared.component, nil
}

